#!/usr/bin/env node
/**
 * @file Builds apps/api/src/platform/auth/policy-common-passwords.ts from a public, frequency-
 * ordered password list (ASVS 5.0 V6.2.4: "top 3000 passwords that match the policy").
 * @module scripts
 *
 * Usage: node scripts/build-common-passwords.mjs <list.txt> [count=5000]
 * Source used for v0.6.6: SecLists `Passwords/Common-Credentials/Pwdb_top-1000000.txt`
 * (MIT licence, Daniel Miessler; sha256 recorded in the generated file).
 *
 * Only passwords that our policy would otherwise ACCEPT (12–128 characters, printable) are kept,
 * in frequency order, lower-cased and de-duplicated. They are stored as truncated SHA-256 hashes
 * (16 hex characters) rather than plain text: the module stays small, secret scanners do not
 * flag random-looking entries, and the repository does not carry the (sometimes offensive)
 * plain words. 64-bit prefixes make accidental collisions with a user's password negligible.
 */
import { createHash } from 'node:crypto';
import { readFileSync, writeFileSync } from 'node:fs';
import { basename, resolve } from 'node:path';

const [src, countArg] = process.argv.slice(2);
if (!src) {
  console.error('Usage: node scripts/build-common-passwords.mjs <list.txt> [count]');
  process.exit(2);
}
const count = Number(countArg ?? 5000);
const raw = readFileSync(src);
const seen = new Set();
const hashes = [];
for (const line of raw.toString('utf8').split(/\r?\n/)) {
  const p = line.normalize('NFC');
  // eslint-disable-next-line no-control-regex -- control characters disqualify an entry
  if (p.length < 12 || p.length > 128 || /[\u0000-\u001f\u007f]/.test(p)) continue;
  const lower = p.toLowerCase();
  if (seen.has(lower)) continue;
  seen.add(lower);
  hashes.push(createHash('sha256').update(lower, 'utf8').digest('hex').slice(0, 16));
  if (hashes.length >= count) break;
}
if (hashes.length < 3000) {
  console.error(`only ${hashes.length} qualifying entries; ASVS asks for at least 3000`);
  process.exit(1);
}
const out = resolve(import.meta.dirname, '../apps/api/src/platform/auth/policy-common-passwords.ts');
const body = `/**
 * @file GENERATED by scripts/build-common-passwords.mjs — do not edit by hand.
 * @module platform/auth
 *
 * The ${hashes.length} most common passwords that satisfy the length policy (12–128), in frequency
 * order, as lower-case SHA-256 prefixes (16 hex). Source: ${basename(src)} (SecLists, MIT licence),
 * sha256 ${createHash('sha256').update(raw).digest('hex')}. ASVS 5.0 V6.2.4.
 */
const HASHES =
  '${hashes.join('')}';

/** Set of 16-hex SHA-256 prefixes of lower-cased common passwords. */
export const POLICY_COMMON_PASSWORD_HASHES: ReadonlySet<string> = new Set(HASHES.match(/.{16}/g) ?? []);
`;
writeFileSync(out, body);
console.log(`wrote ${out} (${hashes.length} entries)`);
